"""Shared static research-card styling, extracted unchanged."""
CARD_STYLE = 'body{margin:0;background:#f4f5f3;color:#182725;font:16px/1.7 system-ui,"Microsoft YaHei",sans-serif}main{max-width:1100px;margin:auto;padding:44px 24px 64px}h1{font-size:30px;line-height:1.35;margin:12px 0 20px}h2{font-size:23px;margin:0}h3{font-size:17px;margin-top:24px}p{max-width:88ch}a{color:#16675c}small,.muted{color:#586b66}header{margin-bottom:28px}.summary{padding:22px 26px;background:#e5eee9;border-left:4px solid #438571}.counts{display:flex;flex-wrap:wrap;gap:12px;margin:24px 0}.counts span{padding:8px 14px;border:1px solid #c9d6cf;border-radius:5px;background:white}.card{padding:25px 28px;margin:22px 0;background:white;border:1px solid #d7dfd9;border-radius:9px}.card-head{display:flex;align-items:center;justify-content:space-between;gap:18px}.badge{font-size:14px;color:#56665f;background:#eef1ed;padding:4px 12px;border-radius:14px}.timeline{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;padding:15px 0}.timeline div{border-top:2px solid #d0ded6;padding-top:9px;font-size:14px}.timeline b{display:block}.table-wrap{overflow-x:auto}table{border-collapse:collapse;width:100%;font-size:14px;font-variant-numeric:tabular-nums}th{text-align:left;background:#eef3f0;white-space:nowrap}td,th{padding:10px 12px;border-bottom:1px solid #e2e8e3}td.numeric{white-space:nowrap}details{border-top:1px solid #e4e8e5;margin-top:20px;padding-top:12px}summary{cursor:pointer;color:#315e52;font-weight:600}code{overflow-wrap:anywhere;font-size:12px}.note{font-size:14px;color:#5c6e65}.warning{background:#fbf3e3;padding:12px 16px;border-radius:5px}footer{margin-top:30px;border-top:1px solid #c9d6cf;padding-top:20px;font-size:13px;color:#607068}@media(max-width:680px){main{padding:24px 14px}h1{font-size:25px}.card{padding:18px 16px}.card-head{align-items:flex-start;flex-direction:column;gap:8px}.timeline{grid-template-columns:1fr}td,th{padding:8px}.summary{padding:16px}}@media print{body{background:white}main{padding:0}.card{break-inside:avoid}details{display:block}summary{display:none}}'
